contract Counter {
    uint256 public number;

    function setNumber(uint256 newNumber) public {
        number = newNumber;
    }

    function increment() public {
        number = number + 1;
    }
}

src/Etch.sol.content:
// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.13;

/// @notice Exercises the `vm.etch` cheatcode: it installs the RUNTIME bytecode
/// of `Impl` onto a bare address that was never deployed, then makes a real
/// external call into that address. The debugger must (a) render the `vm.etch`
/// call itself as a cheatcode frame (4a) and (b) — the point of 4b — resolve the
/// subsequent CALL frame at the etched address against the ETCHED code (Impl),
/// mapping it to Impl's source, WITHOUT corrupting the parent `run` frame.
interface Vm {
    function etch(address who, bytes calldata code) external;
}

/// The implementation whose runtime code is etched onto `TARGET`. Compiled in
/// the same unit as `Etch`, so its CBOR metadata is identifiable from build-info.
contract Impl {
    uint256 public stored;

    function setStored(uint256 v) external returns (uint256) {
        stored = v * 2; // the etched frame executes here → 21*2 = 42
        return stored;
    }
}

contract Etch {
    Vm constant vm = Vm(0x7109709ECfa91a80626fF3989D68f67F5b1DD12D);

    /// A bare address (never deployed) that receives Impl's code via etch.
    address constant TARGET = address(uint160(0xBEEF));

    uint256 public result; // slot 0 — should hold 42 after run()

    function run() external {
        vm.etch(TARGET, type(Impl).runtimeCode); // TARGET.code = Impl runtime
        result = Impl(TARGET).setStored(21); // step INTO etched code → 42
    }
}

src/EtchRaw.sol.content:
// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.13;

/// @notice Exercises `vm.etch` with RAW bytecode that is NOT any compiled
/// contract — there is no CBOR metadata and no matching compilation unit, so
/// the debugger cannot identify a source for the etched frame. 4b must degrade
/// such a frame to EVM-only (disassembly / raw stepping) WITHOUT mis-resolving
/// its PCs against the caller's source map and WITHOUT corrupting the parent
/// `run` frame's stepping.
interface Vm {
    function etch(address who, bytes calldata code) external;
}

contract EtchRaw {
    Vm constant vm = Vm(0x7109709ECfa91a80626fF3989D68f67F5b1DD12D);
    address constant TARGET = address(uint160(0xBEEF));

    bytes32 public out; // slot 0

    function run() external {
        // Minimal valid runtime: PUSH1 1; PUSH1 0; MSTORE; PUSH1 32; PUSH1 0;
        // RETURN → returns the 32-byte word 0x…01. No CBOR, not a known CU.
        vm.etch(TARGET, hex"600160005260206000f3");
        (bool ok, bytes memory ret) = TARGET.call("");
        require(ok, "raw call failed");
        out = abi.decode(ret, (bytes32)); // expect 0x…01
    }
}

src/FixedArrays.sol.content:
// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.13;

/// @notice Exercises FIXED-size arrays (`T[N]`) in both storage and memory,
/// with full-slot (uint256) elements so no packing is involved.
///
/// Storage layout: `fixedArr` occupies slots 0,1,2 inline (no length prefix,
/// no keccak); `sum` is slot 3. A memory `uint256[3]` local is stored inline
/// with no length word — element i at base + i*32.
contract FixedArrays {
    uint256[3] public fixedArr; // slots 0,1,2 (inline)
    uint256 public sum; // slot 3

    function fill() external {
        fixedArr[0] = 111;
        fixedArr[1] = 222;
        fixedArr[2] = 333;

        uint256[3] memory local;
        local[0] = 11;
        local[1] = 22;
        local[2] = 33;

        // Use `local` so it stays live to a clean statement boundary and its
        // memory pointer is resolvable; writes a separate slot so `fixedArr`
        // keeps [111, 222, 333].
        sum = local[0] + local[1] + local[2];
    }
}

src/Modifiers.sol.content:
// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.13;

/// @notice Exercises a MODIFIER for DAP stack reconstruction. Paused inside the
/// modifier body (pre-placeholder) the stack should show [onlyPositive, bump];
/// paused inside the function body (after `_;`) it should show [bump] with the
/// modifier suspended.
contract Modifiers {
    uint256 public stored;

    modifier onlyPositive(uint256 x) {
        uint256 doubled = x * 2; // modifier-body local, pre-placeholder
        require(doubled > 0, "not positive");
        _; // placeholder → runs the function body
    }

    function bump(uint256 x) public onlyPositive(x) returns (uint256 r) {
        r = x + 1; // function body (modifier suspended here)
        stored = r;
    }
}

src/NestedCalls.sol.content:
// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.13;

/// @notice Exercises MULTI-LEVEL internal calls for DAP stack reconstruction:
/// NESTED (outer → level1 → level2) and SEQUENTIAL (outer → level1, then, after
/// it returns, outer → leaf). Used to test the internal-frame pop/re-push path.
contract NestedCalls {
    uint256 public result;

    function outer(uint256 x) public returns (uint256) {
        uint256 a = level1(x); // nested: level1 calls level2
        uint256 b = leaf(x); // sequential: called after level1 returned
        result = a + b;
        return result;
    }

    function level1(uint256 y) internal returns (uint256) {
        uint256 inner = level2(y); // nested call
        return inner + 1;
    }

    function level2(uint256 z) internal returns (uint256) {
        return z * 2; // deepest frame
    }

    function leaf(uint256 w) internal returns (uint256) {
        return w + 100; // sequential sibling frame
    }
}

src/Prank.sol.content:
// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.13;

/// @notice Exercises the `vm.startPrank` cheatcode so we can see what
/// kontrol-node emits for `msg.sender` in the PRANKED callee frame.
///
/// `vm.startPrank(who)` changes the `msg.sender` observed by the *callee* of
/// each subsequent external call (not within the pranking frame itself). So
/// `Target.record()` — called after the prank — should observe `who` as its
/// `msg.sender`, and the trace's per-step `msgSender` inside Target's frame
/// should be `who`, not the Prank contract's address.
interface Vm {
    function startPrank(address who) external;
    function stopPrank() external;
}

contract Target {
    address public seen;

    function record() external returns (address) {
        seen = msg.sender; // should be the pranked address while pranking
        return seen;
    }
}

contract Prank {
    Vm constant vm = Vm(0x7109709ECfa91a80626fF3989D68f67F5b1DD12D);

    address public seenBefore; // msg.sender at Target before the prank
    address public seenDuring; // msg.sender at Target during the prank

    function run(address who) external {
        Target target = new Target();

        seenBefore = target.record(); // no prank → should be this contract

        vm.startPrank(who);
        seenDuring = target.record(); // pranked → should be `who`
        vm.stopPrank();
    }
}

