// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

contract Stepper {
    uint256 public total;

    function run(uint256 x) public {
        uint256 a = x + 1;
        uint256 b = double(a);
        total = a + b;
    }

    function double(uint256 v) internal pure returns (uint256) {
        return v * 2;
    }
}

src/StorageRefs.sol.content:
// SPDX-License-Identifier: UNLICENSED
pragma solidity 0.8.35;

/// Fixture for M7b-3c — storage reference-type decoding.
/// Exercises: a dynamic storage array, a SHORT string (<32 bytes, inline),
/// a LONG string (>=32 bytes, keccak-based), dynamic bytes, a mapping
/// (keys recoverable only via keccak-preimage enumeration from the trace),
/// a value-member storage struct, and an emitted event.
contract StorageRefs {
    struct Point {
        uint256 x;
        uint256 y;
    }

    uint256[] public arr; // slot 0 (len); elements at keccak(0)+i
    string public shortStr; // slot 1 (inline, <32 bytes)
    string public longStr; // slot 2 (len*2+1; data at keccak(2)+)
    bytes public blob; // slot 3 (dynamic bytes)
    mapping(uint256 => uint256) public balances; // slot 4; entry at keccak(key . 4)
    Point public pt; // slots 5 (x), 6 (y)

    event Updated(uint256 indexed key, uint256 value);

    function populate() public {
        arr.push(11);
        arr.push(22);
        arr.push(33);
        shortStr = "hello";
        longStr = "abcdefghijklmnopqrstuvwxyz0123456789"; // 36 bytes -> long
        blob = hex"deadbeef";
        balances[7] = 100;
        balances[9] = 250;
        pt.x = 5;
        pt.y = 6;
        emit Updated(7, 100);
    }
}

src/VarMove.sol.content:
// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.13;

/// @notice Spike fixture: force solc to REORDER a value-type local's stack slot.
/// `amount` is declared first, then used across several multi-arg abi.encode
/// expressions (the pattern that moved `amount` off its declaration slot in
/// uniswap-v4-core). If the height+rank location model is wrong, reading
/// `amount` mid-function returns a stray value.
contract VarMove {
    uint256 public out; // slot 0

    function run() external {
        uint256 amount = 7; // value local (declared first)
        uint256[] memory a = new uint256[](2); // array alloc reshuffles the stack
        bytes memory p0 = abi.encode(a.length, amount, address(this));
        bytes memory p1 = abi.encode(amount, uint256(9), false, "");
        out = amount + a.length + p0.length + p1.length; // amount used again
    }
}

src/VarMoveParams.sol.content:
// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.13;

/// @notice viaIR reproducer for value-type PARAMETER stack locations.
/// `probe(p, q)` takes two value params, derives a local, and uses all three
/// across multi-arg abi.encode expressions that make the Yul stack scheduler
/// reorder slots. Reading `p`/`q`/`s` mid-function must return their true values.
contract VarMoveParams {
    uint256 public out; // slot 0

    function probe(uint256 p, uint256 q) external returns (uint256) {
        uint256 s = p + q; // local derived from params
        bytes memory e0 = abi.encode(p, q, s, address(this));
        bytes memory e1 = abi.encode(q, p, false, "");
        out = p + q + s + e0.length + e1.length; // params + local used again, late
        return out;
    }
}

